// Criterios de HERO ganador
const products = $input.all[0].json.data || $input.all;
const ganadores = [];
for (const p of products) {
 const views = p.videoViews || p.sold || 0;
 const precio = parseFloat(p.sellPrice || p.price || 100);
 const peso = parseFloat(p.weight || 0.3);
 // SCORE
 let score = 0;
 if (views > 50000) score += 30;
 if (precio < 20 && precio > 4) score += 30; // margen x3 en México
 if (peso < 0.5) score += 20; // envío barato
 if (p.rating > 4.5) score += 20;
 if (score >= 80) ganadores.push({...p, hunterScore: score});
}
return ganadores.map(p => ({json: p}));
